CREATE TABLE IF NOT EXISTS market_regime_v2_snapshot (id INTEGER PRIMARY KEY, trade_date DATE NOT NULL, input_hash VARCHAR(64) NOT NULL, version VARCHAR(64) NOT NULL, previous_state VARCHAR(32), current_state VARCHAR(32) NOT NULL, raw_state VARCHAR(32) NOT NULL, state_reasons_json JSON NOT NULL, cooldown_remaining INTEGER NOT NULL, confirmation_count INTEGER NOT NULL, input_coverage NUMERIC(14,6) NOT NULL, source_snapshot_hash VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT uq_regime_v2_trade_hash_version UNIQUE (trade_date,input_hash,version));
CREATE TABLE IF NOT EXISTS deployment_v22_run (id INTEGER PRIMARY KEY, run_id VARCHAR(64) NOT NULL UNIQUE, trade_date DATE NOT NULL, v2_run_id VARCHAR(64) NOT NULL, input_hash VARCHAR(64) NOT NULL UNIQUE, regime_state VARCHAR(32) NOT NULL, candidate_before INTEGER NOT NULL, after_regime INTEGER NOT NULL, after_concentration INTEGER NOT NULL, triggered_count INTEGER NOT NULL, config_snapshot JSON NOT NULL, status VARCHAR(32) NOT NULL, shadow_only BOOLEAN NOT NULL, llm_calls INTEGER NOT NULL, external_calls INTEGER NOT NULL, orders_created INTEGER NOT NULL, source_hashes_json JSON NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS deployment_v22_result (id INTEGER PRIMARY KEY, run_id VARCHAR(64) NOT NULL, trade_date DATE NOT NULL, stock_code VARCHAR(32) NOT NULL, stock_name VARCHAR(128), pool_type VARCHAR(32) NOT NULL, industry VARCHAR(128), cluster_id VARCHAR(128), strategy_id VARCHAR(32) NOT NULL, admission_score NUMERIC(14,6), regime_state VARCHAR(32) NOT NULL, deployment_status VARCHAR(32) NOT NULL, deployment_reason VARCHAR(128) NOT NULL, position_multiplier NUMERIC(14,6) NOT NULL, crowding_status VARCHAR(32) NOT NULL, crowding_reason VARCHAR(128) NOT NULL, retained_rank_in_sector INTEGER, industry_candidate_count_before INTEGER NOT NULL, industry_candidate_count_after INTEGER NOT NULL, industry_pool_ratio NUMERIC(14,6), trigger_status VARCHAR(32) NOT NULL, trigger_reasons_json JSON NOT NULL, trigger_scores_json JSON NOT NULL, version VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT uq_deploy_v22_run_stock_pool UNIQUE (run_id,stock_code,pool_type));
CREATE TABLE IF NOT EXISTS market_adjusted_evaluation (id INTEGER PRIMARY KEY, run_id VARCHAR(64) NOT NULL, trade_date DATE NOT NULL, stock_code VARCHAR(32) NOT NULL, pool_type VARCHAR(32) NOT NULL, benchmark_type VARCHAR(32), benchmark_code VARCHAR(128), benchmark_quality VARCHAR(32) NOT NULL, benchmark_missing_reason VARCHAR(128), metrics_json JSON NOT NULL, version VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT uq_market_adjusted_run_stock_pool UNIQUE (run_id,stock_code,pool_type));
